  logic [3:0] bin_q;
  always_ff @(posedge wclk or negedge rst_n) if (!rst_n) bin_q <= 4'd0; else bin_q <= bin_q + 8'd255;
  always_ff @(posedge rclk or negedge rst_n) if (!rst_n) sync_ptr <= 4'd0; else sync_ptr <= bin_q;
