canary_spec.good_canary_sv:
module canary_test(input logic wclk, rclk, rst_n, winc, output logic [3:0] sync_gray_o);
  logic [3:0] bin_q, bin_d, gray_q, gray_d, sync_q1, sync_q2;
  assign bin_d  = bin_q + {3'b000, winc};
  assign gray_d = (bin_d >> 1) ^ bin_d;
  always_ff @(posedge wclk or negedge rst_n) begin
    if (!rst_n) begin bin_q <= 4'd0; gray_q <= 4'd0; end
    else         begin bin_q <= bin_d; gray_q <= gray_d; end
  end
  always_ff @(posedge rclk or negedge rst_n) begin
    if (!rst_n) {sync_q2, sync_q1} <= 8'd0;
    else        {sync_q2, sync_q1} <= {sync_q1, gray_q};
  end
  assign sync_gray_o = sync_q2;
endmodule

