canary_spec.good_canary_sv:
module canary_test(input logic clkA, clkB, rst_n, send_en, input logic [7:0] data_i, output logic [7:0] data_o, output logic busy_o);
  logic [7:0] data_hold_q;
  logic req_tog_q, req_b1, req_b2, req_b3, ack_a1, ack_a2;
  assign busy_o = req_tog_q ^ ack_a2;
  always_ff @(posedge clkA or negedge rst_n) begin
    if (!rst_n) begin data_hold_q <= 8'd0; req_tog_q <= 1'b0; end
    else if (send_en && !busy_o) begin data_hold_q <= data_i; req_tog_q <= ~req_tog_q; end
  end
  always_ff @(posedge clkB or negedge rst_n) begin
    if (!rst_n) begin {req_b3, req_b2, req_b1} <= 3'b000; data_o <= 8'd0; end
    else begin
      {req_b3, req_b2, req_b1} <= {req_b2, req_b1, req_tog_q};
      if (req_b2 ^ req_b3) data_o <= data_hold_q;
    end
  end
  always_ff @(posedge clkA or negedge rst_n) begin
    if (!rst_n) {ack_a2, ack_a1} <= 2'b00;
    else        {ack_a2, ack_a1} <= {ack_a1, req_b2};
  end
endmodule

